function stageLabel(record){const f=deriveEventFlow(record);return record.paused&&f.done.publish&&!record.ended?'운영 일시중지':({editor:'게임 제작',review:'브랜드 검토',publish:'게시 준비',operate:'운영 중',report:'운영 종료'})[f.entry]}
const explicitTable=eventTable;eventTable=function(){let h=explicitTable().replace('<th>상태</th>','<th>현재 단계</th>').replace('<thead>','<colgroup><col class="event-title-col"><col class="event-channel-col"><col class="event-stage-col"><col class="event-task-col"><col class="event-period-col"></colgroup><thead>');for(const row of allEventRows()){const pattern=new RegExp('(<tr[^>]*data-open-event="'+esc(row.e[0]).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'"[\\s\\S]*?<td>[\\s\\S]*?</td><td[^>]*>[\\s\\S]*?</td><td>)<span class="pill ([^"]*)">[^<]*</span>');h=h.replace(pattern,(_,prefix,cls)=>prefix+pill(stageLabel(row.record),cls))}return h};
const explicitHome=home;home=function(){return explicitHome().replace(/<a href="#workspace">[^<]*워크스페이스 관리 →<\/a>/,'').replace(/(data-filter="검토 중"[^>]*>)검토 중/,'$1브랜드 검토').replace(/(data-filter="시작 예정"[^>]*>)시작 예정/,'$1게시 준비').replace(/(data-filter="진행 중"[^>]*>)진행 중/,'$1운영 중')};
const explicitSteps=steps;steps=function(active){return explicitSteps(active).replace(/(<div class="event-header">[\s\S]*?<\/h1>)<span class="pill [^"]*">[^<]*<\/span>/,'$1'+pill(stageLabel(captureEvent())))};
const activeSendingRows=sendingRows;sendingRows=function(){return activeSendingRows().filter(r=>r.event===state.eventName&&allEventRows().some(e=>e.e[0]===r.event&&e.brand.id===state.brandId&&e.flow.status==='진행 중'))};
const activeSendingBody=sendingBody;sendingBody=function(){return activeSendingBody().replace(/<select id="send-event"[\s\S]*?<\/select>/,`<strong class="sending-event-name">${esc(state.eventName)}</strong>`)};
const currentSendingOperate=operate;operate=function(){return currentSendingOperate().replace('>브랜드 발송 이력</button>','>행사 발송 이력</button>')};
const scopedHistory=openSendingHistory;openSendingHistory=function(){scopedHistory();const title=document.getElementById('send-history-title');if(title)title.textContent='행사 발송 이력'};
const compactAccountShell=shell;shell=function(body){let h=compactAccountShell(body);h=h.replace(/<section class="organization-card">[\s\S]*?<\/section>/,`<section class="plan-summary" aria-label="구독 및 사용 현황"><div class="plan-summary-head">${lineIcon('workspace')}<strong>Agency 플랜</strong></div><dl><div><dt>이번 달 행사 패스</dt><dd>2건</dd></div><div><dt>관리 워크스페이스</dt><dd>${brands.length}개</dd></div></dl></section><div class="account-company">스테이지원 커뮤니케이션</div>`);return h};
state.resultPreview='won';state.resultPrizeIndex=0;
function resultVariant(){return state.resultPreview==='lost'?'lost':'won'}
function resultCopy(id){const saved=state.settings.resultMessages?.[resultVariant()]?.[id];if(saved!==undefined)return saved;return ({won:{title:'축하합니다!\n경품에 당첨되었어요.',copy:'아래에서 경품과 수령 방법을 확인하세요.',button:'수령 안내 확인'},lost:{title:'아쉽지만,\n이번에는 꽝이에요.',copy:'행사에 참여해주셔서 감사합니다.',button:'마치기'}})[resultVariant()][id]}
function resultControls(){return `<div class="result-controls"><div class="field"><label for="result-variant">미리 볼 결과</label><select id="result-variant"><option value="won" ${resultVariant()==='won'?'selected':''}>경품 당첨</option><option value="lost" ${resultVariant()==='lost'?'selected':''}>꽝</option></select></div>${resultVariant()==='won'?`<div class="field"><label for="result-prize">당첨 경품</label><select id="result-prize">${rewards().map((p,i)=>`<option value="${i}" ${state.resultPrizeIndex===i?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>`:''}</div>`}
function resultOutcome(){const prize=rewards()[state.resultPrizeIndex]||rewards()[0];if(resultVariant()==='lost')return '<div class="result-outcome losing" data-layer="outcome"><span>게임 결과</span><strong>꽝</strong><p>당첨된 경품이 없습니다.</p></div>';if(!prize)return '<div class="result-outcome" data-layer="outcome"><strong>등록된 경품이 없습니다.</strong></div>';const mobile=/모바일|상품권|문자/.test(prize.delivery),coupon=/쿠폰/.test(prize.delivery);return `<div class="result-outcome" data-layer="outcome"><span>당첨 경품</span><strong>${esc(prize.name)}</strong><p>${esc(prize.delivery)}</p>${coupon?'<div class="result-code">WELCOME10</div>':mobile?'<p>등록한 휴대전화로 발송됩니다.<br>010-****-1234</p>':`<div class="result-code">WIN-0248</div><p>${esc(state.settings.pickup||state.basic.place||'현장 안내 데스크')}에서 당첨 코드를 보여주세요.</p>`}</div>`}
const outcomeCanvas=layerCanvas;layerCanvas=function(){if(state.studioPage!=='결과')return outcomeCanvas();const t=currentTemplate();return `<div class="editable-phone" data-component="EditableCanvas" style="--stage:${t.stage};--paper:${t.paper};--ink:${t.ink};--accent:${t.accent};background:${t.paper}">${state.layers.filter(l=>l.visible&&l.id!=='game').map(l=>`<div data-layer="${l.id}" class="editable-layer ${l.id}-layer ${state.layerId===l.id?'selected':''}" style="${l.id==='button'?`background:${l.color};font-size:${l.size}px`:`color:${l.color};font-size:${l.size}px`}">${esc(['title','copy','button'].includes(l.id)?resultCopy(l.id):l.text)}</div>${l.id==='title'?resultOutcome():''}`).join('')}</div>`};
const outcomeProps=properties;properties=function(){if(state.studioPage!=='결과')return outcomeProps();if(state.layerId==='outcome')return resultControls()+`<h3>게임 결과</h3><p class="mini-label">경품명과 수령 방법은 경품·수령 설정을 반영합니다.</p>`;let h=outcomeProps();if(['title','copy','button'].includes(state.layerId))h=h.replace(/(<textarea id="layer-text">)[\s\S]*?(<\/textarea>)/,'$1'+esc(resultCopy(state.layerId))+'$2');return resultControls()+h};
const outcomeSwitch=switchStudioPage;switchStudioPage=function(page){if(page==='결과')state.layerId='outcome';outcomeSwitch(page);if(page==='결과'){state.layerId='outcome';render()}};
const outcomeEdit=changeLayer;changeLayer=function(key,value){if(state.studioPage==='결과'&&key==='text'&&['title','copy','button'].includes(state.layerId)){state.settings.resultMessages=state.settings.resultMessages||{};const messages=state.settings.resultMessages[resultVariant()]||(state.settings.resultMessages[resultVariant()]={});messages[state.layerId]=value;invalidateApproval();document.getElementById('layer-canvas').innerHTML=layerCanvas();bindStudio();return}outcomeEdit(key,value)};
const outcomeOpen=openWorkspaceEvent;openWorkspaceEvent=function(n){state.resultPreview='won';state.resultPrizeIndex=0;outcomeOpen(n)};
const outcomeBind=bind;bind=function(){outcomeBind();const variant=document.getElementById('result-variant');if(variant)variant.onchange=()=>{state.resultPreview=variant.value;render()};const prize=document.getElementById('result-prize');if(prize)prize.onchange=()=>{state.resultPrizeIndex=+prize.value;render()}};
const explicitBrandRows=brandRows;brandRows=function(b,sending){if(sending)return explicitBrandRows(b,true);return `<div class="table-wrap"><table class="brand-event-table"><thead><tr><th>행사명</th><th>운영 방식</th><th>현재 단계</th><th>기간</th></tr></thead><tbody>${b.list.slice().sort((a,c)=>eventStatusPriority(deriveEventFlow(state.eventMemory[eventKey(b.id,a[0])]).status)-eventStatusPriority(deriveEventFlow(state.eventMemory[eventKey(b.id,c[0])]).status)).filter(v=>eventChannelMatches(state.eventMemory[eventKey(b.id,v[0])]?.basic)).map(v=>{const record=state.eventMemory[eventKey(b.id,v[0])],flow=record?deriveEventFlow(record):null,status=flow?.status||v[1];return `<tr class="clickable event-navigation-row" tabindex="0" data-open-event="${esc(v[0])}" data-event-brand="${b.id}" data-event-status="${status}" aria-label="${esc(v[0])} 행사 열기"><td><strong>${esc(v[0])}</strong></td><td class="event-channel">${eventChannel(record?.basic)}</td><td>${pill(record?stageLabel(record):status,status==='검토 중'?'review':status==='시작 예정'?'scheduled':status==='종료'?'ended':'')}</td><td class="dim">${esc(record?eventPeriod(record.basic):'')}</td></tr>`}).join('')||'<tr><td colspan="4" class="empty-events">조건에 맞는 행사가 없습니다.</td></tr>'}</tbody></table></div>`};
render();

// Workspace rows and counts use the same saved records as the global event list.
const recordBrandDetail=brandDetail;brandDetail=function(){const b=currentBrand();for(const v of b.list){const record=state.eventMemory[eventKey(b.id,v[0])];if(record)v[1]=deriveEventFlow(record).status}b.events=b.list.length;b.active=b.list.filter(v=>v[1]!=='종료').length;return recordBrandDetail()};
